<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">.venv/bin/python</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> -c</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span></span>
